Value.Code:
// ALT-014: fim do alívio da Bracell. O trem sai com os vazios pelo circuito do GestorDeCirculacao, de ré:
// intervalo4000_c -> b -> a -> marginal_c -> marginal_b -> marginal_a -> via2_f ... via2_a -> via2_intermar_c..a -> railwayTrack199 -> val_via2 -> DVs
Trem trem = (Trem) agent;
traceln(String.format("[%.1f][Bracell][para_circVzs] trem=%d vagoes=%d -> circulacao", time(), trem.getId(), main().getNumeroDeVagoes(trem)));

// ALT-061: a Bracell só informa a saída; o GestorDeAlivios solta a trava,
// devolve a Bracell para terminais_pmc e entrega o trem ao GestorDeCirculacao
trem.faixa_atual   = main().gestorDeCirculacao.faixa_intervalo4000_c;
trem.proxima_faixa = main().gestorDeCirculacao.faixa_intervalo4000_b;

main().gestorDeAlivios.retornar_alivio_pmc(trem);

if (car instanceof Vagao) {
    ((Vagao) car).setSegmento("celulose");
	((Vagao) car).setTerminal(main().bracell);
	((Vagao) car).ferrovia = "rumo"; // ALT-014: ferrovia do trem de teste
}
if (car instanceof Locomotiva) {
    ((Locomotiva) car).ferrovia = "rumo"; // ALT-014: guardar_loco precisa da ferrovia
}

// ALT-014: o trem de carregados ocupa a linha 5000/6000 até sair a loco (recuar3)
{ {
	main().gestorDeCirculacao.rp_linha5000,
	main().gestorDeCirculacao.rp_linha6000
} }
